/*For Un-stratified log-rank test and KM estimates at time points*/
ods output HomTests={logrank} Quartiles={km_q} means={means} CensoredSummary={censorsum} ProductLimitEstimates={rates};
proc lifetest data={indata} conftype=loglog alpha=0.05 alphaqt=0.05 method=km outsurv={surv} timelist=xx reduceout;
