/* {Stratified} Hazard Ratio {of A vs B} (95% CI) [c] */
ods output HazardRatios={hr} estimates={test};
proc phreg data={indata};
     class {trtgrp} (ref = "{B}") / param=ref; /*specify the reference arm in (ref=’’)*/
     strata {strata1} {strata2}; /*only needed for stratified test*/
     model {SurTime}*{Censored(1)}={trtgrp} / rl alpha=0.05 ties=efron;
     hazardratio {trtgrp} / alpha=0.05 diff=ref;
     estimate {trtgrp} {1} / testvalue=Ln_HR0; /*only needed for non-inferiority test. “estimate {trtgrp} 1” assigns 1 as the coefficient to be applied to the non-inferiority statistical test assign Ln_HR0=ln(HR0) where HR0 is the non-inferiority test boundary*/
run;
ods output close;

proc means data={indata} n mean std median q1 q3 min max;
    var {variable};
	by {trtgrp};
	output out={summary} (drop=_TYPE_ _FREQ_) n=n mean=mean std=std median=median q1=q1 q3=q3 min=min max=max;
run;
